class TimeMap:
    def __init__(self):
        self.store: dict[str, list[tuple[int, str]]] = defaultdict(list)

    def set(self, key: str, value: str, timestamp: int) -> None:
        store = self.store
        store[key].append((timestamp, value))  # viz:set

    def get(self, key: str, timestamp: int) -> str:
        entries = self.store.get(key, [])
        lo, hi = 0, len(entries) - 1
        ans = ""
        while lo <= hi:
            mid = (lo + hi) // 2
            if entries[mid][0] <= timestamp:  # viz:check
                ans = entries[mid][1]  # viz:fits
                lo = mid + 1
            else:
                hi = mid - 1  # viz:too_late
        return ans  # viz:done
